// CloudtainerML rev0033 — Contribution-weight geometry attribution probe.
// Inspired by Contribution Weights. Not a reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){if(c=='"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'"';}
struct Regime{string name; double attn_signal, value_norm_signal, alignment_signal, cancellation, rare_tail, cost_pressure; int seed;};
struct Row{string regime,method; double kept_support, output_error, cost, tail_miss, cancel_error, regret, score;};
static double C(double x){return max(0.0,min(1.0,x));}
static Row eval(const Regime&r,const string&m){double support=0,err=0,cost=0.25,tail=0,cancel=0; if(m=="attention_mass_topk"){support=.50+.38*r.attn_signal-.20*r.rare_tail; err=.28+.34*(1-r.attn_signal)+.22*r.cancellation+.18*r.rare_tail; tail=.45*r.rare_tail; cancel=.35*r.cancellation;}
 else if(m=="value_norm_topk"){support=.42+.42*r.value_norm_signal-.12*r.cancellation; err=.25+.26*(1-r.value_norm_signal)+.18*r.cancellation+.20*(1-r.alignment_signal); tail=.22*r.rare_tail; cancel=.30*r.cancellation;}
 else if(m=="alignment_only"){support=.40+.43*r.alignment_signal; err=.24+.30*(1-r.alignment_signal)+.32*(1-r.value_norm_signal); tail=.28*r.rare_tail; cancel=.18*r.cancellation;}
 else if(m=="contribution_weight_topk"){support=.58+.16*r.attn_signal+.16*r.value_norm_signal+.18*r.alignment_signal; err=.16+.13*(1-r.attn_signal)+.12*(1-r.value_norm_signal)+.10*(1-r.alignment_signal)+.10*r.cancellation; tail=.12*r.rare_tail; cancel=.12*r.cancellation; cost=.29;}
 else if(m=="contribution_plus_tail_guard"){support=.62+.12*r.attn_signal+.15*r.value_norm_signal+.17*r.alignment_signal; err=.15+.10*(1-r.value_norm_signal)+.10*(1-r.alignment_signal)+.09*r.cancellation+.04*r.rare_tail; tail=.05*r.rare_tail; cancel=.10*r.cancellation; cost=.34;}
 else if(m=="random_keep"){support=.25; err=.62+.15*r.rare_tail; tail=.70*r.rare_tail; cancel=.50*r.cancellation; cost=.18;}
 else if(m=="oracle_contribution"){support=.92; err=.05+.03*r.cancellation; tail=.02*r.rare_tail; cancel=.03*r.cancellation; cost=.31;}
 support=C(support); err=C(err); tail=C(tail); cancel=C(cancel); double score=err+.18*cost*r.cost_pressure+.28*tail+.22*cancel-.08*support; return {r.name,m,support,err,cost,tail,cancel,0,score};}
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0033_CONTRIBUTION_WEIGHT_GEOMETRY_SMOKE.json"; vector<Regime> regs={{"attention_is_enough",.90,.60,.65,.12,.18,.70,1},{"high_value_low_attention",.25,.95,.70,.16,.55,.75,2},{"alignment_dominates",.52,.55,.95,.12,.28,.72,3},{"canceling_values",.70,.76,.52,.92,.25,.80,4},{"rare_tail_contribution",.48,.72,.76,.30,.94,.85,5},{"low_cost_attribution",.55,.70,.70,.22,.35,1.30,6}}; vector<string> methods={"attention_mass_topk","value_norm_topk","alignment_only","contribution_weight_topk","contribution_plus_tail_guard","random_keep","oracle_contribution"}; vector<Row> rows; map<string,int>winners,nonoracle; for(auto&r:regs){vector<Row> cand; for(auto&m:methods)cand.push_back(eval(r,m)); double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand)x.regret=max(0.0,x.score-best); auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[b->method]++; auto no=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_contribution")return false; if(b.method=="oracle_contribution")return true; return a.score<b.score;}); nonoracle[no->method]++; rows.insert(rows.end(),cand.begin(),cand.end());}
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0033\",\n  \"probe\": \"contribution_weight_geometry\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Attention mass alone is a weak retention/attribution proxy when value magnitude, direction, or cancellation matters; contribution-style scoring earns promotion as a guard field.\",\n    \"screen_regret_fields\": [\"output_error\", \"tail_miss\", \"cancel_error\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"kept_support\": "<<r.kept_support<<", \"output_error\": "<<r.output_error<<", \"cost\": "<<r.cost<<", \"tail_miss\": "<<r.tail_miss<<", \"cancel_error\": "<<r.cancel_error<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n");} f<<"  ]\n}\n";}
